type local struct{mu sync.Mutex;hits map[string]int}
func(l *local)RoundTrip(r *http.Request)(*http.Response,error){l.mu.Lock();l.hits[r.URL.Path]++;l.mu.Unlock();body:="ok";ct:="text/plain";switch r.URL.Path{case "/":body=`<script src="/app.js"></script>`;ct="text/html";case "/app.js":body="const x=\"/api/items\";\n//# sourceMappingURL=app.js.map\n";ct="application/javascript";case "/app.js.map":body=`{"version":3,"sources":["source.ts"],"names":[],"mappings":"AAAA"}`;ct="application/json"};return &http.Response{StatusCode:200,Header:http.Header{"Content-Type":{ct}},Body:io.NopCloser(strings.NewReader(body)),Request:r},nil}
func main(){cmd:=&cobra.Command{};cmd.Flags().Int("concurrent",1,"");cmd.Flags().Int("depth",0,"");cmd.Flags().Bool("quiet",true,"");cmd.Flags().String("user-agent","witness","");site,_:=url.Parse("http://collector.example/");c:=core.NewCrawler(site,cmd);t:=&local{hits:map[string]int{}};c.C.WithTransport(t);c.LinkFinderCollector.WithTransport(t);c.Start(true);c.C.Wait();c.LinkFinderCollector.Wait();c.C.Wait();c.LinkFinderCollector.Wait();t.mu.Lock();defer t.mu.Unlock();if t.hits["/app.js"]!=1||t.hits["/api/items"]!=1||t.hits["/app.js.map"]!=0{panic(fmt.Sprint(t.hits))};fmt.Println("BASELINE script and endpoint fetched; sourceMappingURL never requested");fmt.Println("CONTROL real HTML to script to LinkFinder to endpoint chain: 1,1,1")}
